INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Wird die Hostanzahl mit 2^(32-m) - 2 berechnet?', 2, '[{"text": "Ja", "correct": true, "because": "Formel für nutzbare Hosts"}, {"text": "Nein", "correct": false, "because": "Korrekte Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele nutzbare Hosts hat /24?', 3, '[{"text": "254", "correct": true, "because": "2^(32-24) - 2 = 256 - 2"}, {"text": "256", "correct": false, "because": "Ohne Abzug"}, {"text": "252", "correct": false, "because": "Falsche Subtraktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /30 hat 2 Hosts. b) Die -2 steht für Netzwerk und Broadcast.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 2^(32-30) - 2, b) korrekte Erklärung"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Hostanzahl?', 4, '[{"text": "Netzwerkbits", "correct": false, "because": "Bestimmen m"}, {"text": "Subtraktion von 2", "correct": false, "because": "Netzwerk und Broadcast"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /32 nutzbare Hosts hat?', 2, '[{"text": "Nein", "correct": true, "because": "2^(32-32) - 2 = -2, also 0"}, {"text": "Ja", "correct": false, "because": "Keine Hosts möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Hosts ergeben sich bei /26?', 3, '[{"text": "62", "correct": true, "because": "2^(32-26) - 2 = 64 - 2"}, {"text": "64", "correct": false, "because": "Ohne Abzug"}, {"text": "60", "correct": false, "because": "Falsche Subtraktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren bestimmen die Hostanzahl?', 5, '[{"text": "Netzwerkbits (m)", "correct": true, "because": "In 2^(32-m)"}, {"text": "Subtraktion von 2", "correct": true, "because": "Netzwerk und Broadcast"}, {"text": "Protokolltyp", "correct": false, "because": "Irrelevant"}, {"text": "Bandbreite", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /28 hat 14 Hosts. b) Die Formel zählt auch Netzwerkadressen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) wird abgezogen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Hostanzahl?', 4, '[{"text": "Netzwerkbits", "correct": false, "because": "Bestimmen m"}, {"text": "Exponentiation", "correct": false, "because": "Teil der Formel"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat /16 65.534 Hosts?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-16) - 2 = 65.536 - 2"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele nutzbare Hosts hat /20?', 4, '[{"text": "4.094", "correct": true, "because": "2^(32-20) - 2 = 4.096 - 2"}, {"text": "4.096", "correct": false, "because": "Ohne Abzug"}, {"text": "4.092", "correct": false, "because": "Falsche Subtraktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass /31 keine nutzbaren Hosts hat. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-31) - 2 = 0"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Hostanzahl-Berechnung?', 3, '[{"text": "Netzwerkbits (m)", "correct": true, "because": "Bestimmt Exponent"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /29 hat 6 Hosts. b) Die -2 ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "-2 ist Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hostanzahlen passen zu diesen Masken?', 5, '[{"text": "/24 = 254", "correct": true, "because": "2^8 - 2"}, {"text": "/30 = 2", "correct": true, "because": "2^2 - 2"}, {"text": "/16 = 65.532", "correct": false, "because": "65.534"}, {"text": "/32 = 1", "correct": false, "because": "0 Hosts"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Hostanzahl unwichtig?', 3, '[{"text": "Netzwerkbits", "correct": false, "because": "Bestimmen m"}, {"text": "Subtraktion", "correct": false, "because": "Netzwerk und Broadcast"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat /27 30 Hosts?', 3, '[{"text": "Ja", "correct": true, "because": "2^(32-27) - 2 = 32 - 2"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /8 16.382 Hosts hat?', 2, '[{"text": "Nein", "correct": true, "because": "2^(32-8) - 2 = 16.777.214"}, {"text": "Ja", "correct": false, "because": "Falsche Zahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Hosts hat /25?', 4, '[{"text": "126", "correct": true, "because": "2^(32-25) - 2 = 128 - 2"}, {"text": "128", "correct": false, "because": "Ohne Abzug"}, {"text": "124", "correct": false, "because": "Falsche Subtraktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske erlaubt 1.022 Hosts?', 3, '[{"text": "/22", "correct": true, "because": "2^(32-22) - 2 = 1.024 - 2"}, {"text": "/24", "correct": false, "because": "Nur 254"}, {"text": "/20", "correct": false, "because": "4.094"}]');
